'use strict';
window.MAP_REFERENCE={source:'用户提供的陆家嘴完整边界模型',localGrid:[1800,1320],coordinateSystem:'Local meters, unreferenced',extent:{minX:-450,minY:-330,maxX:1350,maxY:990}};
(function(){
const width=1800,height=1320,minX=-450,maxY=990,bounds=L.latLngBounds([[0,0],[height,width]]),map=window.missionMap=L.map('geoMap',{crs:L.CRS.Simple,zoomControl:false,minZoom:-4,maxZoom:3,zoomSnap:.25});
L.imageOverlay('assets/lujiazui-map.png?v=expanded1',bounds).addTo(map);L.svgOverlay(document.getElementById('map'),bounds,{interactive:true}).addTo(map);let routeBounds=bounds;
const buildingLabelLayer=L.layerGroup().addTo(map),buildingMarkers=[],labelOffsets={aurora:[-68,12],'mirae-asset':[12,-22],'pudong-shangrila':[-98,-8],'shanghai-tower':[-66,10],'jin-mao':[12,-22],swfc:[18,8],'golden-landmark':[-82,12],hsbc:[-62,-22],'huaneng-united':[10,10],'huaxia-bank':[12,-18],'times-finance':[-58,12],'yincheng-10':[10,-18],'cmg-tower':[-66,8],'new-shanghai-international':[10,-20],'shanghai-information':[-72,8]};function refreshBuildingLabels(){const detailed=map.getZoom()>=-1.25||document.body.classList.contains('map-expanded');for(const item of buildingMarkers){const element=item.marker.getElement();if(element)element.classList.toggle('map-building-label--hidden',item.tier>1&&!detailed)}document.getElementById('mapLoadStatus').textContent=`陆家嘴扩大模型 · ${detailed?'16 栋建筑名称':'7 个主要地标 · 放大显示更多建筑'}`};window.renderMapBuildingLabels=landmarks=>{buildingLabelLayer.clearLayers();buildingMarkers.length=0;for(const landmark of landmarks||[]){const tier=landmark.tier||1,label=document.createElement('span'),dot=document.createElement('i'),text=document.createElement('b'),offset=labelOffsets[landmark.id]||(tier>1?[9,-6]:[12,-8]);text.textContent=landmark.shortName||landmark.name;label.title=landmark.name;text.style.setProperty('--label-x',offset[0]+'px');text.style.setProperty('--label-y',offset[1]+'px');label.append(dot,text);const icon=L.divIcon({className:`map-building-label map-building-label--tier-${tier}`,html:label,iconSize:null,iconAnchor:[0,0]}),marker=L.marker([maxY-landmark.point[1],landmark.point[0]-minX],{icon,interactive:false,keyboard:false,zIndexOffset:800-tier}).addTo(buildingLabelLayer);buildingMarkers.push({marker,tier})}requestAnimationFrame(refreshBuildingLabels)};map.on('zoomend',refreshBuildingLabels);
window.focusMissionRoute=points=>{routeBounds=L.latLngBounds(points.map(p=>[maxY-p[1],p[0]-minX])).pad(.4);map.fitBounds(routeBounds,{padding:[20,20]})};
L.control.zoom({position:'topright',zoomInTitle:'放大',zoomOutTitle:'缩小'}).addTo(map);map.fitBounds(bounds);
document.getElementById('fitMap').onclick=()=>map.fitBounds(routeBounds);document.getElementById('baseLayer').hidden=true;document.getElementById('mapLoadStatus').textContent='陆家嘴扩大模型 · 7 个主要地标';
new ResizeObserver(()=>{map.invalidateSize();map.fitBounds(routeBounds,{padding:[4,4]})}).observe(document.getElementById('geoMap'));
})();
